CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS schema_migrations (version TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS boards (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL CHECK (length(trim(name)) > 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workflow_columns (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), board_id UUID NOT NULL REFERENCES boards(id) ON DELETE CASCADE, name TEXT NOT NULL CHECK (length(trim(name)) > 0), position INTEGER NOT NULL DEFAULT 0, canvas_x INTEGER NOT NULL DEFAULT 80, canvas_y INTEGER NOT NULL DEFAULT 80, is_initial BOOLEAN NOT NULL DEFAULT false, is_terminal BOOLEAN NOT NULL DEFAULT false, UNIQUE(board_id,name));
CREATE UNIQUE INDEX IF NOT EXISTS one_initial_column_per_board ON workflow_columns(board_id) WHERE is_initial;
CREATE TABLE IF NOT EXISTS transitions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),board_id UUID NOT NULL REFERENCES boards(id) ON DELETE CASCADE,from_column_id UUID NOT NULL REFERENCES workflow_columns(id) ON DELETE CASCADE,to_column_id UUID NOT NULL REFERENCES workflow_columns(id) ON DELETE CASCADE,action_name TEXT NOT NULL DEFAULT '',CHECK(from_column_id <> to_column_id),UNIQUE(from_column_id,to_column_id));
CREATE TABLE IF NOT EXISTS tasks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),board_id UUID NOT NULL REFERENCES boards(id) ON DELETE CASCADE,column_id UUID NOT NULL REFERENCES workflow_columns(id),title TEXT NOT NULL CHECK(length(trim(title))>0),description TEXT NOT NULL DEFAULT '',priority TEXT NOT NULL DEFAULT 'normal' CHECK(priority IN('low','normal','high','urgent')),due_date DATE,completed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS start_date DATE;
CREATE TABLE IF NOT EXISTS labels (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),board_id UUID NOT NULL REFERENCES boards(id) ON DELETE CASCADE,name TEXT NOT NULL,color TEXT NOT NULL DEFAULT '#5f6b7a',UNIQUE(board_id,name));
CREATE TABLE IF NOT EXISTS task_labels (task_id UUID NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,label_id UUID NOT NULL REFERENCES labels(id) ON DELETE CASCADE,PRIMARY KEY(task_id,label_id));
CREATE TABLE IF NOT EXISTS task_transitions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),task_id UUID NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,from_column_id UUID REFERENCES workflow_columns(id) ON DELETE CASCADE,to_column_id UUID NOT NULL REFERENCES workflow_columns(id) ON DELETE CASCADE,transition_id UUID REFERENCES transitions(id) ON DELETE SET NULL,source TEXT NOT NULL CHECK(source IN('web','mcp')),occurred_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS task_comments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),task_id UUID NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,author TEXT NOT NULL DEFAULT 'Du',body TEXT NOT NULL CHECK(length(trim(body)) > 0),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS tasks_by_board_column ON tasks(board_id,column_id);
